328:     /**
329:      * @notice Returns the total BDV in beanstalk.
330:      * @dev The total BDV may differ from the instaneous BDV,
331:      * as BDV is asyncronous.
332:      * Note We get the silo Tokens, not the whitelisted tokens
333:      * to account for grown stalk from dewhitelisted tokens.
334:      */
335:     function getTotalBdv() internal view returns (uint256 totalBdv) {
336:         AppStorage storage s = LibAppStorage.diamondStorage();
337:         address[] memory siloTokens = LibWhitelistedTokens.getSiloTokens();
338:         for (uint256 i; i < siloTokens.length; ++i) {
339:             totalBdv = totalBdv.add(s.sys.silo.balances[siloTokens[i]].depositedBdv);
340:         }
341:     }
342: 
343:     /**
344:      * @notice Returns the average grown stalk per BDV.
345:      * @dev `totalBDV` refers to the total BDV deposited in the silo.
346:      */
347:     function getAverageGrownStalkPerBdv() internal view returns (uint256) {
348:         AppStorage storage s = LibAppStorage.diamondStorage();
349:         uint256 totalBdv = getTotalBdv();
350:         if (totalBdv == 0) return 0;
351:         return s.sys.silo.stalk.div(totalBdv).sub(STALK_BDV_PRECISION);
352:     }
353: 
354:     /**
355:      * @notice Returns the ratio between the bean and
356:      * the max LP gauge points per BDV.
357:      * @dev s.sys.seedGauge.beanToMaxLpGpPerBdvRatio is a number between 0 and 100e18,
358:      * where f(0) = MIN_BEAN_MAX_LPGP_RATIO and f(100e18) = MAX_BEAN_MAX_LPGP_RATIO.
359:      * At the minimum value (0), beans should have half of the
360:      * largest gauge points per BDV out of the LPs.
361:      * At the maximum value (100e18), beans should have the same amount of
362:      * gauge points per BDV as the largest out of the LPs.
363:      */
364:     function getBeanToMaxLpGpPerBdvRatioScaled(
365:         uint256 beanToMaxLpGpPerBdvRatio
366:     ) internal view returns (uint256) {
367:         AppStorage storage s = LibAppStorage.diamondStorage();
368:         uint256 beanMaxLpGpRatioRange = s.sys.seedGaugeSettings.maxBeanMaxLpGpPerBdvRatio -
369:             s.sys.seedGaugeSettings.minBeanMaxLpGpPerBdvRatio;
370:         return
371:             beanToMaxLpGpPerBdvRatio.mul(beanMaxLpGpRatioRange).div(ONE_HUNDRED_PERCENT).add(
372:                 s.sys.seedGaugeSettings.minBeanMaxLpGpPerBdvRatio
373:             );
374:     }
375: }
